    int[] destination = end;

    // Initialize a stack to keep track of n-tersections to visit
    Stack<int[]> toVisit = new Stack<>();

    // Add the starting n-tersection to the stack
    toVisit.add(start);

    // Loop until the stack is empty or the destination is found
    while (!toVisit.isEmpty()) {
        // Get the current n-tersection from the stack
        int[] current = toVisit.pop();

        // Check if the current n-tersection is the destination
        if (current[0] == destination[0] && current[1] == destination[1]) {
            // If the current n-tersection is the destination, return "can be travelled"
            return "can be travelled";
        }

        // Check if the current n-tersection has already been visited
        if (visited[current[0]][current[1]]) {
            // If the current n-tersection has already been visited, continue to the next n-tersection
            continue;
        }

        // Mark the current n-tersection as visited
        visited[current[0]][current[1]] = true;

        // Add the current n-tersection's neighbors to the stack
        for (int[] neighbor : getNeighbors(current, paths)) {
            toVisit.add(neighbor);
        }
    }

